class Solution:
    def pivotIndex(self, nums: List[int]) -> int:
        # Step 1: Pre-calculate the total sum of the array
        total_sum = sum(nums)
        left_sum = 0

        # Step 2: Iterate and check the balance condition
        for i, num in enumerate(nums):
            # Balance: LeftSum == TotalSum - LeftSum - CurrentNum
            if left_sum == total_sum - left_sum - num:
                return i
            # Update left_sum for the next index
            left_sum += num

        return -1

class Solution:
    def partitionDisjoint(self, A: List[int]) -> int:
        left_max = A[0]
        curr_max = A[0]
        partition_idx = 0

        for i in range(1, len(A)):
            curr_max = max(curr_max, A[i])

            # If A[i] < left_max, it violates the rule, so we expand the left partition
            if A[i] < left_max:
                partition_idx = i
                left_max = curr_max

        return partition_idx + 1

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left = 0

        # Step 1: Find the longest sorted prefix
        while left + 1 < n and arr[left] <= arr[left + 1]:
            left += 1

        if left == n - 1:
            return 0  # Array is already fully sorted

        # Step 2: Find the longest sorted suffix
        right = n - 1
        while right > 0 and arr[right - 1] <= arr[right]:
            right -= 1

        # Step 3: Base cases (keep only prefix OR only suffix)
        ans = min(n - left - 1, right)

        # Step 4: Two pointers to merge prefix and suffix
        i, j = 0, right
        while i <= left and j < n:
            if arr[i] <= arr[j]:
                ans = min(ans, j - i - 1)
                i += 1
            else:
                j += 1

        return ans
